-- 002_npidata_v2.sql
--
-- Redesign the raw `npidata` table for the V2 files (CLAUDE.md §4, §6.1):
-- * utf8mb4 instead of latin1.
-- * Every column except NPI becomes TEXT. Raw dates stay text (MM/DD/YYYY), as in the CSV.
--   Row size: InnoDB's worst-case check counts up to 40 bytes per TEXT column (329 × 40 > 8126),
--   so with innodb_strict_mode=ON (the 8.4 default) even this design is rejected (ERROR 1118).
--   Actual rows always fit: InnoDB moves long TEXT values off-page and keeps a 20-byte pointer, so
--   a row with every column filled needs about 329 × 20 + 330 × 2 bytes ≈ 7.3 KB. Short values stay
--   inline. Hence strict mode is turned off for this statement only (and for the loader's
--   CREATE TABLE npidata_staging LIKE npidata). Needs SESSION_VARIABLES_ADMIN.
-- * Drop the old secondary indexes: searching uses the projection tables (Stage 3), and the
--   indexes slow down bulk loads.
-- * Add Is_Deactivated (maintained by the loader) and Loaded_From (source zip of each row).
--
-- One ALTER statement, so it is atomic. Rebuilds the table: takes several minutes on the full data.

SET SESSION innodb_strict_mode = OFF;

ALTER TABLE `npidata`
  DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  MODIFY COLUMN `NPI` CHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  MODIFY COLUMN `Entity_Type_Code` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  MODIFY COLUMN `Replacement_NPI` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  MODIFY COLUMN `Employer_Identification_Number_EIN` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  MODIFY COLUMN `Provider_Organization_Name_Legal_Business_Name` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  MODIFY COLUMN `Provider_Last_Name_Legal_Name` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  MODIFY COLUMN `Provider_First_Name` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  MODIFY COLUMN `Provider_Middle_Name` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
